torch::Tensor depthwise_conv_h(torch::Tensor x, torch::Tensor weight,
                                c10::optional<torch::Tensor> bias_opt,
                                int64_t strideH, int64_t strideW,
                                int64_t padH, int64_t padW,
                                int64_t dilH) {
