import os
import sys
import subprocess
def _find_cutlass_include():
    """Locate a CUTLASS include directory that provides cute/tensor.hpp."""
    candidates = []
    cutlass_home = os.environ.get("CUTLASS_HOME") or os.environ.get("CUTLASS_PATH")
    if cutlass_home:
        candidates.append(os.path.join(cutlass_home, "include"))
        candidates.append(cutlass_home)
    try:
        import cutlass  # nvidia-cutlass pip package, if installed
        candidates.append(os.path.join(os.path.dirname(cutlass.__file__), "include"))
    except ImportError:
        pass
    candidates += [
        "/usr/local/cutlass/include",
        "/opt/cutlass/include",
        "/usr/include/cutlass/include",
        "/usr/local/include/cutlass/include",
    ]
    for c in candidates:
        if c and os.path.isfile(os.path.join(c, "cute", "tensor.hpp")):
            return c
    # Fallback: try installing the nvidia-cutlass pip package, which ships
    # the cute/ and cutlass/ headers needed by this extension.
    try:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "--quiet", "nvidia-cutlass"])
        import importlib
        if "cutlass" in sys.modules:
            importlib.reload(sys.modules["cutlass"])
        import cutlass
        cand = os.path.join(os.path.dirname(cutlass.__file__), "include")
        if os.path.isfile(os.path.join(cand, "cute", "tensor.hpp")):
            return cand
    except Exception:
        pass
    # No CUTLASS checkout / pip package could be located in this
    # environment. Rather than failing hard, fall back to a minimal
    # in-source shim (see CUTE_USE_SHIM below) that reimplements just the
    # handful of cute:: entry points this kernel relies on, so the same
    # cute::Tensor-based indexing code path can still be compiled.
    return None
CUTLASS_INCLUDE = _find_cutlass_include()
