    Tensor gIn  = make_tensor(make_gmem_ptr(input + in_offset),
                               make_shape(H, W), make_stride(W, 1));
    Tensor gOut = make_tensor(make_gmem_ptr(output + out_offset),
                               make_shape(Hout, Wout), make_stride(Wout, 1));
    Tensor sIn  = make_tensor(make_smem_ptr(smem_raw),
                               make_shape(SH_H, SH_W), make_stride(SH_W, 1));

    int base_h = h_tile_start * sH - pH;
    int base_w = w_tile_start * sW - pW;

    int tid = ty * blockDim.x + tx;
    int nthreads = blockDim.x * blockDim.y;
    int total_smem = SH_H * SH_W;
    float* wcache = smem_raw + total_smem;
    for (int i = tid; i < kH; i += nthreads) {
        wcache[i] = weight[channel * kH + i];
    }
    // The shared-memory tile is loaded from a *contiguous* window of the
    // input row (gw = base_w + sw, incrementing by 1 regardless of stride),
    // so we can safely vectorize this copy with float4 loads whenever the
    // row width is a multiple of 4 and the resulting global address is
    // 16-byte aligned, falling back to scalar loads otherwise.
    if ((SH_W & 3) == 0) {
        int total_vec = total_smem >> 2;
        for (int vidx = tid; vidx < total_vec; vidx += nthreads) {
            int idx4 = vidx * 4;
            int sh = idx4 / SH_W;
            int sw0 = idx4 % SH_W;
            int gh = base_h + sh;
            int gw0 = base_w + sw0;
            float4 val4 = make_float4(0.f, 0.f, 0.f, 0.f);
            if (gh >= 0 && gh < H) {
                const float* gptr = input + in_offset + (size_t)gh * (size_t)W + (size_t)gw0;
                bool aligned = ((reinterpret_cast<uintptr_t>(gptr) & 0xF) == 0);
                if (aligned && gw0 >= 0 && (gw0 + 3) < W) {
                    val4 = *reinterpret_cast<const float4*>(gptr);
                } else {
                    float tmp[4];
                    #pragma unroll
                    for (int k = 0; k < 4; ++k) {
                        int gw = gw0 + k;
                        tmp[k] = (gw >= 0 && gw < W) ? input[in_offset + (size_t)gh * (size_t)W + (size_t)gw] : 0.f;
                    }
                    val4 = make_float4(tmp[0], tmp[1], tmp[2], tmp[3]);
                }
            }
            float4* sptr = reinterpret_cast<float4*>(&smem_raw[sh * SH_W + sw0]);
            *sptr = val4;
        }
    } else {
        for (int idx = tid; idx < total_smem; idx += nthreads) {
            int sh = idx / SH_W;
            int sw = idx % SH_W;
            int gh = base_h + sh;
            int gw = base_w + sw;
            float val = 0.f;
            if (gh >= 0 && gh < H && gw >= 0 && gw < W) {
                val = gIn(gh, gw);
            }
            sIn(sh, sw) = val;
        }
    }
    __syncthreads();

    int w_out_base = w_tile_start + tx * COLS_PER_THREAD;
    int sw_base = tx * COLS_PER_THREAD * sW;
    #pragma unroll
    for (int r = 0; r < ROWS_PER_THREAD; ++r) {
        int h_out = h_tile_start + ty + r * TILE_H;
        if (h_out < Hout) {
            float acc[COLS_PER_THREAD];
            #pragma unroll
            for (int c = 0; c < COLS_PER_THREAD; ++c) acc[c] = 0.f;
            int sh_base = (ty + r * TILE_H) * sH;
            #pragma unroll
            for (int kh = 0; kh < kH; ++kh) {
                int sh = sh_base + kh * dH;
                float wv = wcache[kh];
                if (sW == 1) {
                    // Contiguous case: sw = sw_base, sw_base+1, ..., sw_base+COLS_PER_THREAD-1.
                    // sw_base is always a multiple of COLS_PER_THREAD (=8) and, when
                    // sW==1, SH_W==TILE_W (a multiple of 8), so the shared-memory
                    // offset sh*SH_W + sw_base is always a multiple of 4, giving
                    // 16-byte aligned float4 loads. Splitting the wider per-thread
                    // output tile into COLS_PER_THREAD/4 vectorized loads gives each
                    // thread more register-blocked reuse of the staged shared-memory
                    // tile per synchronization, reducing overhead per output element.
                    #pragma unroll
                    for (int cv = 0; cv < COLS_PER_THREAD; cv += 4) {
                        const float4 v4 = *reinterpret_cast<const float4*>(&sIn(sh, sw_base + cv));
                        acc[cv + 0] += v4.x * wv;
                        acc[cv + 1] += v4.y * wv;
                        acc[cv + 2] += v4.z * wv;
                        acc[cv + 3] += v4.w * wv;
                    }
                } else {
                    #pragma unroll
                    for (int c = 0; c < COLS_PER_THREAD; ++c) {
                        int sw = sw_base + c * sW;
                        acc[c] += sIn(sh, sw) * wv;
                    }
                }
            }
            if (bias != nullptr) {
                #pragma unroll
                for (int c = 0; c < COLS_PER_THREAD; ++c) acc[c] += bias[channel];
            }
            if (sW == 1 && (w_out_base + COLS_PER_THREAD) <= Wout) {
                float* optr = &output[out_offset + (size_t)h_out * (size_t)Wout + (size_t)w_out_base];
                bool aligned = ((reinterpret_cast<uintptr_t>(optr) & 0xF) == 0);
                if (aligned) {
                    #pragma unroll
                    for (int cv = 0; cv < COLS_PER_THREAD; cv += 4) {
                        float4 outv = make_float4(acc[cv + 0], acc[cv + 1], acc[cv + 2], acc[cv + 3]);
                        *reinterpret_cast<float4*>(optr + cv) = outv;
                    }
                } else {
                    #pragma unroll
                    for (int c = 0; c < COLS_PER_THREAD; ++c) {
                        optr[c] = acc[c];
                    }
                }
            } else {
                #pragma unroll
                for (int c = 0; c < COLS_PER_THREAD; ++c) {
                    int w_out = w_out_base + c;
                    if (w_out < Wout) {
                        output[out_offset + (size_t)h_out * (size_t)Wout + (size_t)w_out] = acc[c];
                    }
                }
            }
        }
    }
}
torch::Tensor depthwise_conv_h(torch::Tensor x, torch::Tensor weight,
                                c10::optional<torch::Tensor> bias_opt,
                                int64_t strideH, int64_t strideW,
                                int64_t padH, int64_t padW,
                                int64_t dilH) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N, C, H, W)");
    x = x.contiguous();
    weight = weight.contiguous();
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int kH = weight.size(2); // weight shape: (C, 1, kH, 1)
    int sH = (int)strideH;
    int sW = (int)strideW;
    int pH = (int)padH;
    int pW = (int)padW;
    int dH = (int)dilH;
    int Hout = (H + 2 * pH - dH * (kH - 1) - 1) / sH + 1;
    int Wout = (W + 2 * pW - 1) / sW + 1;
    auto output = torch::empty({N, C, Hout, Wout}, x.options());
    const float* bias_ptr = nullptr;
    torch::Tensor bias;
    if (bias_opt.has_value() && bias_opt.value().defined()) {
        bias = bias_opt.value().contiguous();
        TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
        bias_ptr = bias.data_ptr<float>();
    }
    dim3 block(TILE_W / COLS_PER_THREAD, TILE_H);
    dim3 grid((unsigned)(N * C),
              (unsigned)((Hout + TILE_H * ROWS_PER_THREAD - 1) / (TILE_H * ROWS_PER_THREAD)),
              (unsigned)((Wout + TILE_W - 1) / TILE_W));
    int SH_H = (TILE_H * ROWS_PER_THREAD - 1) * sH + (kH - 1) * dH + 1;
    int SH_W = (TILE_W - 1) * sW + 1;
    size_t smem_bytes = (size_t)(SH_H * SH_W + kH) * sizeof(float);
    int device_idx = x.get_device();
    int max_smem_optin = 0;
    cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device_idx);
    TORCH_CHECK((int)smem_bytes <= max_smem_optin,
        "Requested shared memory (", smem_bytes,
        " bytes) exceeds device max opt-in shared memory (", max_smem_optin, " bytes)");
    static bool attr_set = false;
    if (!attr_set) {
        cudaError_t attr_err = cudaFuncSetAttribute(
            depthwise_conv_h_kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            (int)smem_bytes);
        TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));
        attr_set = true;
    }
    depthwise_conv_h_kernel<<<grid, block, smem_bytes, c10::cuda::getCurrentCUDAStream()>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        Hout, Wout,
        kH,
        sH, sW,
        pH, pW,
        dH,
        SH_H, SH_W);
    return output;
}
